<?php
require __DIR__.'/config.php';require_login();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(current_user()['role']!=='owner')throw new RuntimeException('Only the owner can record or delete expenses.');$action=$_POST['action']??'';if($action==='save'){$title=trim($_POST['title']??'');$category=trim($_POST['category']??'General');$amount=(float)($_POST['amount']??0);$date=$_POST['expense_date']??date('Y-m-d');$notes=trim($_POST['notes']??'');if(!$title||$amount<=0)throw new RuntimeException('Enter an expense name and amount greater than zero.');$pdo->prepare('INSERT INTO expenses(title,category,amount,notes,user_id,expense_date) VALUES(?,?,?,?,?,?)')->execute([$title,$category,$amount,$notes,current_user()['id'],$date]);flash('Expense recorded.');}elseif($action==='delete'){$pdo->prepare('DELETE FROM expenses WHERE id=?')->execute([(int)$_POST['id']]);flash('Expense deleted.');}}catch(Throwable $ex){flash($ex->getMessage(),'error');}redirect('expenses.php');}
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$st=$pdo->prepare('SELECT e.*,u.name user_name FROM expenses e LEFT JOIN users u ON u.id=e.user_id WHERE expense_date BETWEEN ? AND ? ORDER BY expense_date DESC,e.id DESC');$st->execute([$from,$to]);$rows=$st->fetchAll();$sum=array_sum(array_column($rows,'amount'));$pageTitle='Expenses';require __DIR__.'/partials/header.php';?>
<div class="page-intro"><div><h1>Expenses</h1><p>Track utilities, supplies, restocking, transport, and other costs.</p></div><span class="pill utang">Total: <?=money($sum)?></span></div><div class="two-col"><section class="panel"><div class="panel-heading"><div><h2>Record expense</h2><p>Owner account required.</p></div></div><?php if(current_user()['role']==='owner'):?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><label>Expense title *</label><input name="title" required placeholder="e.g. Electricity bill"><label>Category</label><select name="category"><option>Utilities</option><option>Supplies</option><option>Restocking</option><option>Transport</option><option>Rent</option><option>Maintenance</option><option>General</option></select><label>Amount (₱) *</label><input name="amount" type="number" min=".01" step=".01" required><label>Date</label><input name="expense_date" type="date" value="<?=date('Y-m-d')?>" required><label>Notes</label><textarea name="notes" rows="2"></textarea><button class="btn primary">Save expense</button></form><?php else:?><p class="hint">Cashier accounts can view expenses but only the owner can record them.</p><?php endif;?></section><section class="panel"><div class="panel-heading"><div><h2>Filter expenses</h2><p>Choose a date range.</p></div></div><form class="form-stack"><label>From</label><input type="date" name="from" value="<?=e($from)?>"><label>To</label><input type="date" name="to" value="<?=e($to)?>"><button class="btn secondary">Apply filter</button></form><div class="summary-box"><span>Expense total</span><strong><?=money($sum)?></strong><small><?=count($rows)?> records from <?=e($from)?> to <?=e($to)?></small></div></section></div><section class="panel section-gap"><div class="panel-heading"><div><h2>Expense history</h2><p>Records in selected date range</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Expense</th><th>Category</th><th>Notes</th><th>Recorded by</th><th>Amount</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">No expenses found for this date range.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?=e($r['expense_date'])?></td><td><b><?=e($r['title'])?></b></td><td><?=e($r['category'])?></td><td><?=e($r['notes']?:'—')?></td><td><?=e($r['user_name']?:'—')?></td><td><?=money($r['amount'])?></td><td><?php if(current_user()['role']==='owner'):?><form method="post" onsubmit="return confirm('Delete this expense?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link-danger">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php';?>